"""Embedded dedicated builder assets."""
BUILDER_DOCKERFILE = 'FROM oxidex-self-hosted-runner:2.337.0\nUSER root\nRUN apt-get update && apt-get install -y --no-install-recommends rsync time python3-venv llvm \\\n    && rm -rf /var/lib/apt/lists/* \\\n    && python3 -m venv /opt/uv && /opt/uv/bin/pip install --no-cache-dir uv\nENV UV_PYTHON_INSTALL_DIR=/opt/python\nRUN /opt/uv/bin/uv python install 3.11 \\\n    && mkdir -p /opt/build-tools \\\n    && ln -s "$(/opt/uv/bin/uv python find 3.11)" /opt/build-tools/python3\n# Primary release checksums: https://ziglang.org/download/index.json and\n# https://index.crates.io/ca/rg/cargo-zigbuild. Verify both archives before use.\n# Zig supplies target musl headers/libraries and compiles zip\'s C-backed codecs;\n# the host\'s x86_64 musl-tools alone cannot cross-compile those for ARM64.\nRUN curl --proto \'=https\' --tlsv1.2 -fsS \\\n      https://ziglang.org/download/0.15.2/zig-x86_64-linux-0.15.2.tar.xz -o /tmp/zig.tar.xz \\\n    && echo \'02aa270f183da276e5b5920b1dac44a63f1a49e55050ebde3aecc9eb82f93239  /tmp/zig.tar.xz\' | sha256sum -c - \\\n    && mkdir -p /opt/zig \\\n    && tar -xJf /tmp/zig.tar.xz --strip-components=1 -C /opt/zig \\\n    && rm /tmp/zig.tar.xz \\\n    && test "$(/opt/zig/zig version)" = 0.15.2 \\\n    && curl --proto \'=https\' --tlsv1.2 -fsS \\\n      https://static.crates.io/crates/cargo-zigbuild/cargo-zigbuild-0.23.4.crate -o /tmp/cargo-zigbuild.crate \\\n    && echo \'0b0c2fe7d5f1a782047272e3fc1cd44214c450776bbde564bf92b9776dc2d781  /tmp/cargo-zigbuild.crate\' | sha256sum -c - \\\n    && mkdir -p /tmp/cargo-zigbuild-source \\\n    && tar -xzf /tmp/cargo-zigbuild.crate --strip-components=1 -C /tmp/cargo-zigbuild-source \\\n    && rm /tmp/cargo-zigbuild.crate \\\n    && chown -R 1001:1001 /tmp/cargo-zigbuild-source\n# SDK-free Darwin framework interface, derived from core-foundation-sys 0.8.7\n# (MIT), commit 652bab0a62d87df8a974ffad2ad9f7be218a8b56. No implementation\n# or proprietary SDK is included. See builder/DARWIN-STUB-NOTICE.md.\nRUN install -d -m 0755 /opt/opensourceDarwinStubs/CoreFoundation.framework \\\n    && printf \'%s\\n\' \\\n      \'--- !tapi-tbd\' \\\n      \'tbd-version: 4\' \\\n      \'targets: [ arm64-macos, x86_64-macos ]\' \\\n      \'install-name: /System/Library/Frameworks/CoreFoundation.framework/Versions/A/CoreFoundation\' \\\n      \'current-version: 1.0\' \\\n      \'compatibility-version: 1.0\' \\\n      \'exports:\' \\\n      \'  - targets: [ arm64-macos, x86_64-macos ]\' \\\n      \'    symbols: [ _CFRelease, _CFTimeZoneCopySystem, _CFTimeZoneGetName, _CFTimeZoneResetSystem, _CFStringGetCStringPtr, _CFStringGetLength, _CFStringGetBytes ]\' \\\n      \'...\' > /opt/opensourceDarwinStubs/CoreFoundation.framework/CoreFoundation.tbd \\\n    && printf \'%s\\n\' \\\n      \'CoreFoundation interface symbols derived from core-foundation-sys 0.8.7.\' \\\n      \'Source: https://github.com/servo/core-foundation-rs/tree/652bab0a62d87df8a974ffad2ad9f7be218a8b56/core-foundation-sys\' \\\n      \'Licensed under MIT (selected from MIT OR Apache-2.0).\' \\\n      \'\' \\\n      \'Copyright (c) 2012-2013 Mozilla Foundation\' \\\n      \'\' \\\n      \'Permission is hereby granted, free of charge, to any person obtaining a copy\' \\\n      \'of this software and associated documentation files (the "Software"), to deal\' \\\n      \'in the Software without restriction, including without limitation the rights\' \\\n      \'to use, copy, modify, merge, publish, distribute, sublicense, and/or sell copies\' \\\n      \'of the Software, and to permit persons to whom the Software is furnished to\' \\\n      \'do so, subject to the following conditions:\' \\\n      \'\' \\\n      \'The above copyright notice and this permission notice shall be included in\' \\\n      \'all copies or substantial portions of the Software.\' \\\n      \'\' \\\n      \'THE SOFTWARE IS PROVIDED "AS IS", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR\' \\\n      \'IMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY,\' \\\n      \'FITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE\' \\\n      \'AUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER\' \\\n      \'LIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING FROM,\' \\\n      \'OUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN\' \\\n      \'THE SOFTWARE.\' > /opt/opensourceDarwinStubs/NOTICE \\\n    && chmod 0444 /opt/opensourceDarwinStubs/CoreFoundation.framework/CoreFoundation.tbd /opt/opensourceDarwinStubs/NOTICE\nCOPY entrypoint.py /usr/local/bin/oxidex-build-entrypoint\nRUN chmod 0755 /usr/local/bin/oxidex-build-entrypoint \\\n    && install -m 0444 /dev/null /run/oxidex-build-container\nUSER runner\nENV RUSTUP_HOME=/home/runner/.rustup\nENV PATH=/home/runner/.cargo/bin:/opt/build-tools:/opt/uv/bin:/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin\nRUN curl --proto \'=https\' --tlsv1.2 -fsS https://sh.rustup.rs -o /tmp/rustup-init.sh \\\n    && sh /tmp/rustup-init.sh -y --profile minimal --default-toolchain 1.97.1 \\\n    && rm /tmp/rustup-init.sh \\\n    && rustup component add rustfmt clippy --toolchain 1.97.1 \\\n    && rustup target add --toolchain 1.97.1 x86_64-unknown-linux-musl aarch64-unknown-linux-musl \\\n    && rustup target add --toolchain 1.97.1 aarch64-apple-darwin x86_64-apple-darwin \\\n    && cargo install --locked -j4 just \\\n    && cargo install --locked -j4 cargo-nextest \\\n    && cargo install --locked -j4 --version 0.29.2 cbindgen \\\n    && cargo install --locked -j4 --path /tmp/cargo-zigbuild-source \\\n    && rm -rf /tmp/cargo-zigbuild-source \\\n    && test "$(cargo-zigbuild --version)" = \'cargo-zigbuild 0.23.4\' \\\n    && rustc -vV && cargo -V && cargo nextest --version && cbindgen --version \\\n    && just --version && uv --version && python3 --version \\\n    && /opt/zig/zig version && cargo-zigbuild --version && llvm-strip --version\nENV CARGO_HOME=/cargo\nENV CARGO_TARGET_DIR=/target\nENV UV_CACHE_DIR=/cargo/uv-cache\nWORKDIR /src\nENTRYPOINT ["/usr/bin/python3", "/usr/local/bin/oxidex-build-entrypoint"]\n'
BUILDER_ENTRYPOINT = '#!/usr/bin/env python3\n"""Prove the checkout\'s compiler pin before executing an unprivileged build."""\nimport os\nimport re\nimport subprocess\nimport sys\nfrom pathlib import Path\n\n\ndef main():\n    text = Path(\'/src/rust-toolchain.toml\').read_text()\n    match = re.search(r\'^channel\\s*=\\s*"([0-9]+\\.[0-9]+\\.[0-9]+)"\', text, re.M)\n    if not match:\n        raise RuntimeError(\'A numeric Rust toolchain pin is required\')\n    pin = match[1]\n    compiler = subprocess.check_output([\'rustup\', \'which\', \'--toolchain\', pin, \'rustc\'], text=True).strip()\n    cargo = subprocess.check_output([\'rustup\', \'which\', \'--toolchain\', pin, \'cargo\'], text=True).strip()\n    env = dict(os.environ, RUSTC=compiler)\n    # Pin PATH as well, for just recipes, subprocesses and rustdoc.\n    env[\'PATH\'] = str(Path(compiler).parent) + \':\' + env[\'PATH\']\n    env[\'RUSTDOC\'] = str(Path(compiler).with_name(\'rustdoc\'))\n    env[\'RUSTUP_TOOLCHAIN\'] = pin\n    # Apply to Python/Just as well: the cached router launches a Python job\n    # that invokes Cargo later. Keep Zig caches inside the persistent mounts.\n    env[\'CARGO_ZIGBUILD_ZIG_PATH\'] = \'/opt/zig/zig\'\n    env[\'CARGO_ZIGBUILD_CACHE_DIR\'] = \'/cargo/zigbuild-cache\'\n    env[\'ZIG_GLOBAL_CACHE_DIR\'] = \'/cargo/zig-global-cache\'\n    # Hidden so portable artifact export does not include the compiler cache.\n    env[\'ZIG_LOCAL_CACHE_DIR\'] = \'/target/.zig-cache\'\n    # Zig supplies Darwin libc; only the open-source CF interface stub is added.\n    # Callers append this as a framework search path to their existing flags.\n    env[\'OXIDEX_DARWIN_FRAMEWORK_DIR\'] = \'/opt/opensourceDarwinStubs\'\n    env.pop(\'SDKROOT\', None)\n    print(subprocess.check_output([compiler, \'-vV\'], text=True), flush=True)\n    print(subprocess.check_output([cargo, \'-V\'], text=True), flush=True)\n    command = sys.argv[1:] or [\'cargo\', \'build\', \'--release\', \'--locked\', \'--bin\', \'oxidex\']\n    if command[0] == \'cargo\':\n        command[0] = cargo\n    os.execvpe(command[0], command, env)\n\n\nif __name__ == \'__main__\':\n    main()\n'
HOST_LAUNCHER = '#!/usr/bin/env python3\n"""Root-owned remote builder launcher: fixed mounts, image, UID and limits."""\nimport json\nimport fcntl\nimport os\nimport re\nimport subprocess\nimport sys\nfrom pathlib import Path\n\nROOT = Path(\'/mnt/runner-data/remote-build\')\nALLOWED = {\'cargo\', \'rustc\', \'rustfmt\', \'clippy-driver\', \'just\', \'uv\', \'python3\', \'cbindgen\'}\n\n\ndef validate_project(project):\n    if not re.fullmatch(r\'[a-zA-Z0-9][a-zA-Z0-9_-]{0,63}\', project):\n        raise ValueError(\'Project must be a simple identifier, never a path\')\n    return project\n\n\ndef container_command(project, command, cpus, memory_gib):\n    validate_project(project)\n    if not command or command[0] not in ALLOWED:\n        raise ValueError(\'Unsupported build command\')\n    if cpus < 1 or memory_gib < 1:\n        raise ValueError(\'Resource limits must be positive\')\n    return [\'docker\', \'run\', \'--rm\', \'--user=1001:1001\', f\'--cpus={cpus}\',\n            \'--label=oxidex.remote-build=true\',\n            f\'--memory={memory_gib}g\', f\'--memory-swap={memory_gib}g\', \'--pids-limit=4096\',\n            \'--cap-drop=ALL\', \'--security-opt=no-new-privileges\',\n            \'--entrypoint=/usr/bin/time\',\n            \'-v\', f\'{ROOT}/sources/{project}:/src\',\n            \'-v\', f\'{ROOT}/targets/{project}:/target\', \'-v\', f\'{ROOT}/cargo:/cargo\',\n            \'oxidex-remote-builder:1.97.1\', \'-v\', \'/usr/bin/python3\',\n            \'/usr/local/bin/oxidex-build-entrypoint\', *command]\n\n\ndef checked_path(path):\n    if path.resolve() != path or any(p.is_symlink() for p in (path, *path.parents)):\n        raise ValueError(\'Symlinked builder paths are forbidden\')\n\n\ndef main():\n    if os.geteuid() != 0:\n        raise RuntimeError(\'Invoke this root-owned launcher with sudo\')\n    project = validate_project(sys.argv[1])\n    config = json.loads(Path(\'/etc/oxidex-remote-build.json\').read_text())\n    for path in (ROOT, ROOT/\'sources\', ROOT/\'targets\', ROOT/\'cargo\',\n                 ROOT/\'sources\'/project, ROOT/\'targets\'/project):\n        checked_path(path)\n        path.mkdir(parents=True, exist_ok=True)\n    if sys.argv[2:] == [\'prepare\']:\n        # SSH uploader and container user share access without world-writable data.\n        source = ROOT/\'sources\'/project\n        os.chown(source, int(os.environ.get(\'SUDO_UID\', \'1001\')), 1001)\n        source.chmod(0o2770)\n        for path in (ROOT/\'targets\'/project, ROOT/\'cargo\'):\n            os.chown(path, 1001, 1001)\n        print(source)\n        return\n    command = sys.argv[2:] or [\'cargo\', \'build\', \'--release\', \'--locked\', \'--bin\', \'oxidex\']\n    with open(\'/run/oxidex-build.lock\', \'a\') as lock:\n        fcntl.flock(lock, fcntl.LOCK_SH)\n        if Path(\'/run/oxidex-build-draining\').exists():\n            raise SystemExit(75)\n        raise SystemExit(subprocess.run(container_command(project, command, config[\'cpus\'], config[\'memory_gib\'])).returncode)\n\n\nif __name__ == \'__main__\':\n    main()\n'
